 const cosmeticDefaults=defaults.find(p=>p.id==='cosmetic').kpis;
 const singDefaults=defaults.find(p=>p.id==='sing').kpis;
 const migrated=existing.map(p=>{
  if(p.id==='care')return {...p,source:'Beauty Care'};
  if(p.id==='sing'){
   const existing=Array.isArray(p.kpis)?p.kpis:[];
   const names=new Set(existing.map(k=>k.name));
   return {...p,kpis:[...singDefaults.filter(k=>!names.has(k.name)),...existing]};
  }
  if(p.id==='cosmetic'){
   const existing=Array.isArray(p.kpis)?p.kpis:[];
   const names=new Set(existing.map(k=>k.name));
   return {...p,kpis:[...existing,...cosmeticDefaults.filter(k=>!names.has(k.name))]};
  }
  if(p.id!=='fashion')return p;
  const old=Array.isArray(p.kpis)?p.kpis:[];
  const remap={'잇걸룩 코디':'잇걸룩 수'};
  const updated=old.map(k=>({...k,name:remap[k.name]||k.name})).filter(k=>k.name!=='저장한 코디');
  const names=new Set(updated.map(k=>k.name));
  return {...p,kpis:[...updated,...fashionDefaults.filter(k=>!names.has(k.name))]};
 });
 return [...migrated,...defaults.filter(p=>!existing.some(x=>x.id===p.id))];
