const addMilestone=()=>{if(!draft.title?.trim()||!draft.date||!data.projects.some(p=>p.id===draft.project))return;update(d=>({...d,milestones:[...(d.milestones||[]),{id:crypto.randomUUID(),project:draft.project,title:draft.title.trim(),date:draft.date,notes:draft.notes||'',done:false}]}));close()};
const toggleMilestone=id=>update(d=>({...d,milestones:(d.milestones||[]).map(m=>m.id===id?{...m,done:!m.done}:m)}));
const removeMilestone=id=>{if(!window.confirm('마일스톤을 삭제할까?'))return;update(d=>({...d,milestones:(d.milestones||[]).filter(m=>m.id!==id)}))};
const addLog=()=>{if(!draft.title?.trim()||!data.projects.some(p=>p.id===draft.project))return;update(d=>({...d,logs:[...d.logs,{id:crypto.randomUUID(),project:draft.project,title:draft.title.trim(),date:today(),value:0,kpi:'',notes:draft.notes||''}]}));close()};
const spendFeatured=data.spendFeatured||[];
