const fashionFeatured=normalizeFashionFeatured(data.fashionFeatured);
const toggleFashionFeatured=id=>update(d=>{const old=normalizeFashionFeatured(d.fashionFeatured);return {...d,fashionFeatured:old.includes(id)?old.filter(x=>x!==id):[...old.slice(-1),id]}});
const singFeatured=Array.isArray(data.singFeatured)?data.singFeatured:['trainingCount','trainingMinutes'];
const toggleSingFeatured=id=>update(d=>{const old=Array.isArray(d.singFeatured)?d.singFeatured:['trainingCount','trainingMinutes'];return {...d,singFeatured:old.includes(id)?old.filter(x=>x!==id):[...old.slice(-1),id]}});
const sequenceFeatured=Array.isArray(data.sequenceFeatured)?data.sequenceFeatured:['registered','learned'];
const toggleSequenceFeatured=id=>update(d=>{const old=Array.isArray(d.sequenceFeatured)?d.sequenceFeatured:['registered','learned'];return {...d,sequenceFeatured:old.includes(id)?old.filter(x=>x!==id):[...old.slice(-1),id]}});
const isSequenceProject=p=>p?.id==='sequence'||p?.id==='movement'||String(p?.name||'').trim().toLowerCase()==='sequence'||String(p?.name||'').trim().toLowerCase()==='movement';
const beautyFeatured=(data.beautyFeatured||[]).filter(id=>id==='face'||id==='hair'||id==='input');
const bodyFeatured=(data.bodyFeatured??(data.beautyFeatured||[]).filter(id=>!['face','input'].includes(id))).filter(id=>['gym','strength','stretch','massage','waist','thigh','calf'].includes(id));
const toggleBodyFeatured=id=>update(d=>{const old=d.bodyFeatured??(d.beautyFeatured||[]).filter(x=>!['face','input'].includes(x));return {...d,bodyFeatured:old.includes(id)?old.filter(x=>x!==id):[...old.slice(-1),id]}});
const toggleBeautyFeatured=id=>update(d=>{const old=Array.isArray(d.beautyFeatured)?d.beautyFeatured:[];return {...d,beautyFeatured:old.includes(id)?old.filter(x=>x!==id):[...old.slice(-1),id]}});
const toggleCareFeatured=id=>update(d=>{const old=Array.isArray(d.careFeatured)?d.careFeatured:[];return {...d,careFeatured:old.includes(id)?old.filter(x=>x!==id):[...old.slice(-1),id]}});
const toggleMindFeatured=name=>{update(d=>{const before=Array.isArray(d.mindFeatured)?d.mindFeatured:[];const next=before.includes(name)?before.filter(x=>x!==name):[...before.filter(x=>x!==name).slice(-1),name];return {...d,mindFeatured:next};});};
const toggleSpendFeatured=key=>update(d=>{const prev=d.spendFeatured||[];return {...d,spendFeatured:prev.includes(key)?prev.filter(x=>x!==key):prev.length<2?[...prev,key]:[prev[1],key]}});
const kpiConfig=data.kpiConfig||{};
const linkedKpis=p=>p.kpis.filter(k=>(kpiConfig[p.id]?.visible||[]).includes(k.name));
const featuredKpis=p=>{const chosen=linkedKpis(p);const preferred=kpiConfig[p.id]?.featured||[];return [...chosen].sort((a,b)=>{const ai=preferred.indexOf(a.name),bi=preferred.indexOf(b.name);return (ai<0?999:ai)-(bi<0?999:bi)}).slice(0,2)};
const toggleKpi=(projectId,name)=>update(d=>{const config=d.kpiConfig||{},old=config[projectId]||{},visible=old.visible||[],next=visible.includes(name)?visible.filter(n=>n!==name):[...visible,name];return {...d,kpiConfig:{...config,[projectId]:{...old,visible:next,featured:(old.featured||[]).filter(n=>next.includes(n))}}}});
const toggleKpiFeatured=(projectId,name)=>update(d=>{const config=d.kpiConfig||{},old=config[projectId]||{},current=old.featured||[],next=current.includes(name)?current.filter(n=>n!==name):[...current.slice(-1),name];return {...d,kpiConfig:{...config,[projectId]:{...old,featured:next}}}});
const totalFor=(p,k)=>data.logs.filter(l=>l.project===p.id&&l.kpi===k.name).reduce((s,l)=>s+l.value,0);
const roadmapKpis=p=>{
 const extra={
 spend:[['무지출 데이',30,'일'],['계획 소비율',80,'%']],
 mind:[['호흡',12,'회'],['명상',30,'분'],['만트라',1,'회']],
 care:[['물',2500,'mL'],['만보',6000,'보'],['단백질',60,'g']],
 beauty:[['얼굴 관리율',100,'%'],['헤어 관리율',100,'%'],['기록 입력률',100,'%']],
 fitness:[['헬스장 출석',3,'회'],['근력운동',120,'분'],['스트레칭',90,'분'],['마사지',60,'분']],
 dance:[['등록 동작',20,'개'],['습득 동작',20,'개'],['완성 안무',1,'개']],
 sequence:[['등록 동작',20,'개'],['습득 동작',20,'개'],['완성 안무',1,'개'],['연습 시간',300,'분']],
 movement:[['등록 동작',20,'개'],['습득 동작',20,'개'],['완성 안무',1,'개'],['연습 시간',300,'분']],
 time:[['집중 시간',600,'분']]
 };
 const base=(p?.kpis||[]).map(k=>({name:k.name,target:Number(k.target)||0,unit:k.unit||'',auto:p.kind==='internal'}));
 const names=new Set(base.map(k=>k.name));
 for(const [name,target,unit] of (extra[p?.id]|| (String(p?.name||'').toLowerCase()==='sequence'?extra.sequence:[]))){if(!names.has(name)){base.push({name,target,unit,auto:false});names.add(name)}}
 return base;
};
const roadmapKpiValues=p=>Object.fromEntries(roadmapKpis(p).filter(k=>k.auto).map(k=>[k.name,totalFor(p,k)]));
const pct=(p,k)=>Math.min(100,Math.round(totalFor(p,k)/Math.max(1,k.target)*100));
