if(session&&!cloudReady)return <main className="auth"><div className="authcard"><div className="brandmark">✦</div><h1>90 Day</h1><p>{syncStatus==='error'?'클라우드 데이터 연결에 실패했어요. 기존 기록을 보호하기 위해 편집을 중단했어요. Supabase SQL 설정을 확인해 주세요.':'계정 데이터를 안전하게 불러오는 중…'}</p>{syncStatus==='error'&&<button className="light wide" onClick={()=>supabase.auth.signOut()}>로그아웃</button>}</div></main>;
if(supabase&&!session)return <main className="auth"><div className="authcard"><div className="brandmark">✦</div><h1>90 Day</h1><p>작은 실천을 모아 만드는 90일의 변화</p><div className="auth-switch"><button type="button" className={!register?'selected':''} onClick={()=>{setRegister(false);setAuthError('')}}>로그인</button><button type="button" className={register?'selected':''} onClick={()=>{setRegister(true);setAuthError('')}}>회원가입</button></div><form onSubmit={submitAuth}><label htmlFor="auth-email">이메일</label><input id="auth-email" type="email" autoComplete="email" placeholder="name@example.com" value={email} onChange={e=>setEmail(e.target.value)} required/><label htmlFor="auth-password">비밀번호</label><div className="password-wrap"><input id="auth-password" type={showPassword?'text':'password'} autoComplete={register?'new-password':'current-password'} placeholder="6자 이상" value={password} onChange={e=>setPassword(e.target.value)} minLength={6} required/><button type="button" onClick={()=>setShowPassword(x=>!x)}>{showPassword?'숨기기':'보기'}</button></div><button className="primary" disabled={authBusy}>{authBusy?'처리 중…':register?'계정 만들기':'로그인'}</button></form>{authError&&<p role="status" className="notice">{authError}</p>}<div className="auth-foot">{register?'가입 후 이메일 인증이 필요할 수 있어요.':'계정별로 90일 기록을 안전하게 분리해 저장해요.'}</div></div></main>;
