const visionUrl=path=>supabase.storage.from('project_visions').getPublicUrl(path).data.publicUrl;
const uploadVision=async(e,projectId)=>{
 const files=Array.from(e.target.files||[]);e.target.value='';if(!files.length||!supabase||!session)return;
 setVisionBusy(true);setVisionError('');
 for(const file of files){
  if(!file.type.startsWith('image/')||file.size>8*1024*1024){setVisionError('이미지는 파일당 8MB 이하만 등록할 수 있어요.');continue;}
  const path=`${session.user.id}/${projectId}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;
  const {error}=await supabase.storage.from('project_visions').upload(path,file,{contentType:file.type});
  if(error){setVisionError(error.message);continue;}
  update(d=>({...d,visions:{...d.visions,[projectId]:[...(d.visions?.[projectId]||[]),{path,name:file.name,id:crypto.randomUUID()}]}}));
 }
 setVisionBusy(false);
};
const deleteVision=async(projectId,img)=>{
 if(!window.confirm('이 이미지를 삭제할까요?'))return;
 const {error}=await supabase.storage.from('project_visions').remove([img.path]);
 if(error){setVisionError(error.message);return;}
 update(d=>({...d,visions:{...d.visions,[projectId]:(d.visions?.[projectId]||[]).filter(x=>x.id!==img.id)}}));
};
